const oldGoto=goto;
window.goto=function(where){if(page==='check'&&where!=='check')clearScreenshot();return oldGoto(where);};
document.addEventListener('click',e=>{if(e.target.closest('[data-action="reset"]')){screenshotImg=null;screenshotRectangles=[];screenshotLoaded=false;if(micRecognition){micRecognition.stop();micRecognition=null;}}},true);
if(state.onboarded&&!state.profile.goals.length)state.profile.goals=['unsure'];save();render();
